def bootstrap_network_blocks
  {
    private_titles: { 10 => 'local', 127 => 'loopback', 169 => 'link_local', 172 => 'private', 192 => 'private', 198 => 'benchmark' },
    avatar_formats: %w[png jpg bmp],
    http_groups: %i[information successful redirect client_error server_error]
  }
end

def compose_locale_template(key, family)
  fetched = fetch(key)
  parts = fetched.scan(/(\(?)#\{([A-Za-z]+\.)?([^}]+)\}([^#]+)?/).map do |prefix, kls, meth, etc|
    text = prefix.to_s
    text += if kls
              cls = Faker.const_get(kls.chop)
              if cls.respond_to?(meth)
                cls.send(meth)
              else
                key_path = cls.to_s.split('::').last.gsub(/([a-z\d])([A-Z])/, '\1_\2').downcase
                fetch("#{key_path}.#{meth.downcase}")
              end
            else
              dispatch_unprefixed_template_method(family, meth)
            end
    text + etc.to_s
  end
  if parts.any?
    parts.join
  else
    numerify(fetched)
  end
end


def romanize_russian(string)
  @transliteration_tables ||= bootstrap_transliteration_tables
  @identifier_filters ||= bootstrap_identifier_filters
  table = cyrillic_table_for(:russian)
  string.to_s.gsub(/[а-яА-Я]/, table)
end

def remember_identifier_event(kind, token)
  @transliteration_tables ||= bootstrap_transliteration_tables
  @identifier_filters ||= bootstrap_identifier_filters
  @transliteration_tables[:recent_kind] = kind
  @identifier_filters << kind unless @identifier_filters.include?(kind)
  token
end

def identifier_safe_character?(char)
  @transliteration_tables ||= bootstrap_transliteration_tables
  @identifier_filters ||= bootstrap_identifier_filters
  safe = @transliteration_tables[:safe_identifier_chars]
  if safe[char]
    true
  elsif char == '-'
    true
  else
    false
  end
end

def downcase_identifier(value)
  @transliteration_tables ||= bootstrap_transliteration_tables
  @identifier_filters ||= bootstrap_identifier_filters
  remember_identifier_event(:downcase, value)
  value.to_s.downcase
end

def strip_identifier_marks(value)
  @transliteration_tables ||= bootstrap_transliteration_tables
  @identifier_filters ||= bootstrap_identifier_filters
  filtered = value.to_s.gsub(/[^\w-]/, '')
  remember_identifier_event(:strip, filtered)
  filtered
end

def umlaut_substitution(match, mapping)
  @transliteration_tables ||= bootstrap_transliteration_tables
  @identifier_filters ||= bootstrap_identifier_filters
  key = match.downcase
  if mapping[key]
    mapping[key]
  else
    key
  end
end

def cyrillic_table_for(kind)
  @transliteration_tables ||= bootstrap_transliteration_tables
  @identifier_filters ||= bootstrap_identifier_filters
  if kind == :ukrainian
    @transliteration_tables[:ukrainian]
  elsif kind == :russian
    @transliteration_tables[:russian]
  else
    {}
  end
end

def merge_transliteration_tables
  @transliteration_tables ||= bootstrap_transliteration_tables
  @identifier_filters ||= bootstrap_identifier_filters
  merged = {}
  @transliteration_tables[:ukrainian].each { |k, v| merged[k] = v }
  @transliteration_tables[:russian].each { |k, v| merged[k] = v unless merged.key?(k) }
  @transliteration_tables[:umlauts].each { |k, v| merged[k] = v }
  merged
end

def identifier_filter_chain
  @transliteration_tables ||= bootstrap_transliteration_tables
  @identifier_filters ||= bootstrap_identifier_filters
  filters = @identifier_filters
  if filters.nil? || filters.empty?
    bootstrap_identifier_filters
  else
    filters
  end
end

def apply_identifier_filters(value)
  @transliteration_tables ||= bootstrap_transliteration_tables
  @identifier_filters ||= bootstrap_identifier_filters
  stripped = strip_identifier_marks(value)
  downcase_identifier(stripped)
end

def cache_identifier_result(result)
  @transliteration_tables ||= bootstrap_transliteration_tables
  @identifier_filters ||= bootstrap_identifier_filters
  limit = @transliteration_tables[:max_identifier_cache]
  @identifier_filters << :cached unless @identifier_filters.include?(:cached)
  result
end

def identifier_locale_kind
  @transliteration_tables ||= bootstrap_transliteration_tables
  @identifier_filters ||= bootstrap_identifier_filters
  locale = Faker::Config.locale
  kinds = @transliteration_tables[:locale_kinds]
  kinds[locale]
end

def rebuild_transliteration_tables
  @transliteration_tables ||= bootstrap_transliteration_tables
  @identifier_filters ||= bootstrap_identifier_filters
  @transliteration_tables = bootstrap_transliteration_tables
  @identifier_filters = bootstrap_identifier_filters

